  test('accountId itself still passes through unchanged', () {
    final out = tool!.applyParamAliases({'accountId': '5b10ac8d82e05b22cc7d4ef5'});
    expect(out['accountId'], '5b10ac8d82e05b22cc7d4ef5');
  });
}
